// Disk-skills merge — Phase 7d-5α-A1 (commit 6/9).
//
// Skills can live in two places: in `state.settings.customSkills` (JSON,
// edited by the desktop UI) or as `~/.melo/desktop/skills/<id>/SKILL.md`
// disk files (authored by humans / generated by Claude). This module
// merges the disk side INTO the state object: disk wins on id collision
// (the disk record gets origin='disk' + diskPath + version applied),
// JSON-only skills survive untouched.
//
// Used in two places:
//   • src/desktopStore.js:readStateSnapshot — runs on every state load
//     so disk authoring shows up immediately on app boot.
//   • src/desktopStore.js:reloadDiskSkills — explicit "reload skills
//     from disk" button in the UI.
//
// Per CLAUDE.md §5 (byte-for-byte rule), the body is verbatim from
// desktopStore.js — only the `export` keyword + this file header were
// added.

import { loadSkillsFromDisk } from '../agents/skillsDisk.js';
import { BUILTIN_SKILLS, normalizeCustomSkill } from '../services/skill/skillService.js';

export async function mergeDiskSkillsIntoState(state) {
  let diskSkills = [];
  try {
    diskSkills = await loadSkillsFromDisk();
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn(`[desktopStore] skill disk load failed: ${err.message}`);
    return;
  }
  if (!diskSkills.length) return;
  if (!Array.isArray(state.settings.customSkills)) {
    state.settings.customSkills = [];
  }
  const jsonById = new Map(
    state.settings.customSkills
      .filter(s => s && s.id && s.origin !== 'disk')
      .map(s => [s.id, s]),
  );
  const merged = [];
  const seen = new Set();
  for (const disk of diskSkills) {
    if (!disk || !disk.id) continue;
    const skill = { ...disk, origin: 'disk' };
    // Skip skills whose id shadows a built-in; disk authors should rename.
    if (BUILTIN_SKILLS.some(b => b.id === skill.id)) continue;
    const normalized = normalizeCustomSkill(skill);
    if (!normalized) continue;
    // normalizeCustomSkill resets origin/diskPath/version to defaults,
    // so re-apply from the disk record.
    normalized.origin = 'disk';
    normalized.diskPath = disk.diskPath || null;
    normalized.version = Number.isFinite(disk.version) ? disk.version : 1;
    merged.push(normalized);
    seen.add(normalized.id);
  }
  // Keep JSON skills whose ids don't collide.
  for (const [id, skill] of jsonById) {
    if (!seen.has(id)) merged.push(skill);
  }
  state.settings.customSkills = merged;
}
